class SessionConfig(dict):
    """Holds all settings for a given instance (alias) of ute_btssm."""

    def __init__(self, **kwargs):
        super(SessionConfig, self).__init__(kwargs)

    def __getattr__(self, name):
        return self[name]

    @property
    def ssh_connection_params(self):
        """Returns a tuple containing SSH parameters required to establish connection (ip, port, prompt) or
           None if SSH parameters are not available."""
        return self._retrieve_params(host_ip='host', ssh_port='port', ssh_prompt='prompt')

    @property
    def ssh_login_params(self):
        """Returns tuple containing SSH parameters required to login (username, password) or None if SSH parameters are not available."""
        return self._retrieve_params(ssh_username='username', ssh_password='password')

    def _retrieve_params(self, **kwargs):
        for key, value in kwargs.items():
            if not self._hasattr(self, key):
                return
        return {value: getattr(self, key) for key, value in kwargs.items()}

    def _hasattr(self, value, attr):
        try:
            return hasattr(value, attr)
        except:
            return False


